INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ffed64bb-808d-4e18-82bf-6cb30c92d993', 'life_insurance', NULL, 'What is the difference between term and whole life insurance?', '¿Cuál es la diferencia entre seguro de vida temporal y permanente?', '["Term is temporary coverage; whole life is permanent with cash value", "They are the same", "Term has cash value", "Whole life is temporary"]', '["Temporal es cobertura temporaria; vida entera es permanente con valor en efectivo", "Son lo mismo", "Temporal tiene valor en efectivo", "Vida entera es temporario"]', 0, 'Term life provides coverage for a specific period with no cash value, while whole life provides lifelong coverage and builds cash value.', 'El seguro temporal proporciona cobertura por un período específico sin valor en efectivo, mientras que el de vida entera proporciona cobertura de por vida y acumula valor en efectivo.', true, '2026-01-14 18:28:35.63655', '2026-01-14 18:28:35.63655') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('002a97d2-c088-44e6-b2d9-350a21dfb2a5', 'general_lines', NULL, 'What is the difference between fraud and misrepresentation?', '¿Cuál es la diferencia entre fraude y tergiversación?', '["No difference", "Fraud involves intentional deception; misrepresentation may be unintentional", "Misrepresentation is always criminal", "Fraud only applies to claims"]', '["Sin diferencia", "El fraude involucra engaño intencional; la tergiversación puede ser no intencional", "La tergiversación siempre es criminal", "El fraude solo aplica a reclamos"]', 1, 'Fraud involves intentional deception for gain, while misrepresentation can be either intentional or unintentional false statements.', 'El fraude involucra engaño intencional para obtener ganancia, mientras que la tergiversación puede ser declaraciones falsas intencionales o no intencionales.', true, '2026-01-14 23:13:37.291903', '2026-01-14 23:13:37.291903') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('018bc75a-f9dc-4abd-a5a9-2a165c68a637', 'general_lines', NULL, 'What is a unilateral contract?', '¿Qué es un contrato unilateral?', '["A contract where only one party makes an enforceable promise", "A bilateral contract", "A loan agreement", "A lease agreement"]', '["Un contrato donde solo una parte hace una promesa ejecutable", "Un contrato bilateral", "Un acuerdo de préstamo", "Un contrato de arrendamiento"]', 0, 'Insurance is unilateral because only the insurer makes a legally enforceable promise; the policyholder can stop paying at any time.', 'El seguro es unilateral porque solo el asegurador hace una promesa legalmente ejecutable; el asegurado puede dejar de pagar en cualquier momento.', true, '2026-01-14 18:28:35.716061', '2026-01-14 18:28:35.716061') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('02513cc3-46aa-4716-9e6c-53ae0e79d091', 'general_lines', NULL, 'Who regulates insurance in Texas?', '¿Quién regula los seguros en Texas?', '["Texas Department of Insurance (TDI)", "Federal Insurance Administration", "Texas Real Estate Commission", "Department of Treasury"]', '["Departamento de Seguros de Texas (TDI)", "Administración Federal de Seguros", "Comisión de Bienes Raíces de Texas", "Departamento del Tesoro"]', 0, 'The Texas Department of Insurance (TDI) regulates the insurance industry in Texas.', 'El Departamento de Seguros de Texas (TDI) regula la industria de seguros en Texas.', true, '2026-01-14 18:28:35.678905', '2026-01-14 18:28:35.678905') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('04079454-5fc9-48e6-8580-3ed8e76d0dd9', 'general_lines', NULL, 'What is completed operations coverage?', '¿Qué es la cobertura de operaciones completadas?', '["Coverage during work", "Liability coverage for injuries or damage arising from work completed away from the premises", "Property coverage", "Auto coverage"]', '["Cobertura durante el trabajo", "Cobertura de responsabilidad para lesiones o daños que surgen de trabajo completado fuera de las instalaciones", "Cobertura de propiedad", "Cobertura de auto"]', 1, 'Completed operations coverage provides liability protection for claims arising from work completed by the insured at a location away from the insured''s premises.', 'La cobertura de operaciones completadas proporciona protección de responsabilidad para reclamos que surgen de trabajo completado por el asegurado en una ubicación fuera de las instalaciones del asegurado.', true, '2026-01-14 23:13:37.382439', '2026-01-14 23:13:37.382439') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('04ab2f91-cd68-4954-9d5c-859fe0e5a14a', 'general_lines', NULL, 'What does a Commercial General Liability (CGL) policy primarily cover?', '¿Qué cubre principalmente una póliza de Responsabilidad General Comercial (CGL)?', '["Employee injuries", "Third-party bodily injury and property damage claims", "Auto accidents", "Professional errors"]', '["Lesiones de empleados", "Reclamos de lesiones corporales y daños a la propiedad de terceros", "Accidentes de auto", "Errores profesionales"]', 1, 'A CGL policy provides coverage for third-party claims of bodily injury, property damage, and personal/advertising injury.', 'Una póliza CGL proporciona cobertura para reclamos de terceros por lesiones corporales, daños a la propiedad y lesiones personales/publicitarias.', true, '2026-01-14 23:10:18.083629', '2026-01-14 23:10:18.083629') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('06663448-3467-4a6c-bcdd-7e4dd40195b9', 'general_lines', NULL, 'What is an occurrence in CGL policies?', '¿Qué es una ocurrencia en las pólizas CGL?', '["A planned event", "An accident including continuous or repeated exposure to conditions causing injury or damage", "A claim", "A premium payment"]', '["Un evento planificado", "Un accidente incluyendo exposición continua o repetida a condiciones que causan lesión o daño", "Un reclamo", "Un pago de prima"]', 1, 'An occurrence is defined as an accident, including continuous or repeated exposure to substantially the same general harmful conditions.', 'Una ocurrencia se define como un accidente, incluyendo exposición continua o repetida a sustancialmente las mismas condiciones dañinas generales.', true, '2026-01-14 23:13:37.372893', '2026-01-14 23:13:37.372893') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('09344044-9c14-4b6d-bd69-2f1bd1f07d64', 'general_lines', NULL, 'What is garage liability coverage?', '¿Qué es la cobertura de responsabilidad de garaje?', '["Homeowners coverage for garages", "Liability coverage for auto dealers and repair shops", "Personal auto coverage", "Property coverage only"]', '["Cobertura de propietarios para garajes", "Cobertura de responsabilidad para concesionarios de autos y talleres de reparación", "Cobertura de auto personal", "Solo cobertura de propiedad"]', 1, 'Garage liability coverage provides liability protection for businesses such as auto dealers, repair shops, and service stations.', 'La cobertura de responsabilidad de garaje proporciona protección de responsabilidad para negocios como concesionarios de autos, talleres de reparación y estaciones de servicio.', true, '2026-01-14 23:10:18.246857', '2026-01-14 23:10:18.246857') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0965cd50-9efe-4f70-8663-06053c841bb5', 'general_lines', NULL, 'What is products liability insurance?', '¿Qué es el seguro de responsabilidad por productos?', '["Insurance for product manufacturing", "Coverage for claims arising from products that cause injury or damage", "Coverage for theft of products", "Insurance for product advertising"]', '["Seguro para la fabricación de productos", "Cobertura para reclamos que surgen de productos que causan lesiones o daños", "Cobertura para robo de productos", "Seguro para publicidad de productos"]', 1, 'Products liability insurance covers claims arising from bodily injury or property damage caused by products manufactured, sold, or distributed by the insured.', 'El seguro de responsabilidad por productos cubre reclamos que surgen de lesiones corporales o daños a la propiedad causados por productos fabricados, vendidos o distribuidos por el asegurado.', true, '2026-01-14 23:10:18.162695', '2026-01-14 23:10:18.162695') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0c042660-9a94-410a-a659-8392d910577c', 'general_lines', NULL, 'What is an aleatory contract?', '¿Qué es un contrato aleatorio?', '["A contract where the exchange of value may be unequal, depending on uncertain events", "An equal exchange contract", "A loan agreement", "A lease agreement"]', '["Un contrato donde el intercambio de valor puede ser desigual, dependiendo de eventos inciertos", "Un contrato de intercambio igual", "Un acuerdo de préstamo", "Un contrato de arrendamiento"]', 0, 'Insurance is an aleatory contract because the policyholder may pay premiums and never receive benefits, or receive much more than paid in.', 'El seguro es un contrato aleatorio porque el asegurado puede pagar primas y nunca recibir beneficios, o recibir mucho más de lo pagado.', true, '2026-01-14 18:28:35.707472', '2026-01-14 18:28:35.707472') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0ca64e59-c636-4dd9-ba81-e805bfe1dd98', 'general_lines', NULL, 'What is ordinance or law coverage?', '¿Qué es la cobertura de ordenanza o ley?', '["Legal defense coverage", "Coverage for costs to comply with building codes when rebuilding after a loss", "Professional liability", "Auto coverage"]', '["Cobertura de defensa legal", "Cobertura para costos de cumplir con códigos de construcción al reconstruir después de una pérdida", "Responsabilidad profesional", "Cobertura de auto"]', 1, 'Ordinance or law coverage pays for increased costs to comply with current building codes and laws when repairing or rebuilding after a covered loss.', 'La cobertura de ordenanza o ley paga por costos aumentados para cumplir con códigos de construcción y leyes actuales al reparar o reconstruir después de una pérdida cubierta.', true, '2026-01-14 23:16:55.428521', '2026-01-14 23:16:55.428521') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0cb8e5cc-8deb-4b23-94bb-b928bcd4ae00', 'general_lines', NULL, 'What is the difference between a broker and an agent in Texas?', '¿Cuál es la diferencia entre un corredor y un agente en Texas?', '["No difference", "A broker represents the insured; an agent represents the insurance company", "A broker sells only life insurance", "An agent cannot sell commercial insurance"]', '["Sin diferencia", "Un corredor representa al asegurado; un agente representa a la compañía de seguros", "Un corredor solo vende seguros de vida", "Un agente no puede vender seguros comerciales"]', 1, 'In Texas, a broker legally represents the client/insured, while an agent represents the insurance company in transactions.', 'En Texas, un corredor representa legalmente al cliente/asegurado, mientras que un agente representa a la compañía de seguros en transacciones.', true, '2026-01-14 23:13:37.272496', '2026-01-14 23:13:37.272496') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0cebf35a-65c7-4f1b-b86b-36512a8ffe74', 'general_lines', NULL, 'What is the law of large numbers?', '¿Qué es la ley de los grandes números?', '["A tax law", "A statistical principle that allows insurers to predict losses more accurately with larger samples", "A premium calculation", "A coverage limit"]', '["Una ley fiscal", "Un principio estadístico que permite a los aseguradores predecir pérdidas con mayor precisión con muestras más grandes", "Un cálculo de prima", "Un límite de cobertura"]', 1, 'The law of large numbers states that as the sample size increases, actual results will more closely approximate expected results, allowing accurate loss prediction.', 'La ley de los grandes números establece que a medida que aumenta el tamaño de la muestra, los resultados reales se aproximarán más a los resultados esperados, permitiendo una predicción de pérdidas precisa.', true, '2026-01-14 23:23:20.940729', '2026-01-14 23:23:20.940729') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0d08a702-32bd-48ec-b3b3-afcdcd403558', 'general_lines', NULL, 'What is a captive insurance company?', '¿Qué es una compañía de seguros cautiva?', '["An insurance company held hostage", "An insurance company created by a parent company to insure its own risks", "A standard insurer", "A surplus lines company"]', '["Una compañía de seguros retenida como rehén", "Una compañía de seguros creada por una empresa matriz para asegurar sus propios riesgos", "Un asegurador estándar", "Una compañía de líneas excedentes"]', 1, 'A captive insurance company is formed by a parent company or group to provide coverage primarily for the risks of its owner(s).', 'Una compañía de seguros cautiva es formada por una empresa matriz o grupo para proporcionar cobertura principalmente para los riesgos de su(s) propietario(s).', true, '2026-01-14 23:13:37.360232', '2026-01-14 23:13:37.360232') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0e02d0ef-bf67-48c3-a50d-70a7c35dea38', 'general_lines', NULL, 'What is an additional insured?', '¿Qué es un asegurado adicional?', '["A duplicate policy", "A person or organization added to a policy who receives liability protection", "An exclusion", "A premium discount"]', '["Una póliza duplicada", "Una persona u organización agregada a una póliza que recibe protección de responsabilidad", "Una exclusión", "Un descuento de prima"]', 1, 'An additional insured is a person or organization added to a liability policy who receives protection under that policy''s coverage.', 'Un asegurado adicional es una persona u organización agregada a una póliza de responsabilidad que recibe protección bajo la cobertura de esa póliza.', true, '2026-01-14 23:10:18.178036', '2026-01-14 23:10:18.178036') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0e647051-466c-4a5d-a5ee-2948a9b834f2', 'general_lines', NULL, 'What is personal injury protection (PIP)?', '¿Qué es la protección de lesiones personales (PIP)?', '["Liability coverage", "No-fault coverage for medical expenses and lost wages regardless of who caused the accident", "Property coverage", "Life insurance"]', '["Cobertura de responsabilidad", "Cobertura sin culpa para gastos médicos y salarios perdidos sin importar quién causó el accidente", "Cobertura de propiedad", "Seguro de vida"]', 1, 'PIP is no-fault coverage that pays for medical expenses, lost wages, and other benefits regardless of who is at fault in the accident.', 'PIP es cobertura sin culpa que paga gastos médicos, salarios perdidos y otros beneficios sin importar quién tiene la culpa en el accidente.', true, '2026-01-14 23:16:55.576634', '2026-01-14 23:16:55.576634') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0faa4583-688c-4b54-8ec3-ae99af78480f', 'general_lines', NULL, 'What is utmost good faith in insurance?', '¿Qué es la máxima buena fe en seguros?', '["A sales technique", "The requirement that both parties must deal honestly and disclose all material facts", "A type of policy", "A claims procedure"]', '["Una técnica de ventas", "El requisito de que ambas partes deben actuar honestamente y revelar todos los hechos materiales", "Un tipo de póliza", "Un procedimiento de reclamos"]', 1, 'Utmost good faith requires both the insurer and the insured to deal honestly and disclose all material information relevant to the insurance contract.', 'La máxima buena fe requiere que tanto el asegurador como el asegurado actúen honestamente y revelen toda la información material relevante para el contrato de seguro.', true, '2026-01-14 23:13:37.333363', '2026-01-14 23:13:37.333363') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('11adfd76-0551-411e-9725-851417fe3eed', 'general_lines', NULL, 'What is a large deductible program?', '¿Qué es un programa de deducible grande?', '["A standard insurance program", "A program where the insured retains a significant portion of losses through a high deductible", "A life insurance program", "A health insurance program"]', '["Un programa de seguro estándar", "Un programa donde el asegurado retiene una porción significativa de las pérdidas a través de un deducible alto", "Un programa de seguro de vida", "Un programa de seguro de salud"]', 1, 'A large deductible program allows the insured to retain a significant portion of losses, reducing premium costs while the insurer handles claims administration.', 'Un programa de deducible grande permite al asegurado retener una porción significativa de las pérdidas, reduciendo los costos de prima mientras el asegurador maneja la administración de reclamos.', true, '2026-01-14 23:23:20.952701', '2026-01-14 23:23:20.952701') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('12f2ad6e-2c37-46d8-a7b1-382cf28d534f', 'general_lines', NULL, 'What are the three parties to a surety bond?', '¿Cuáles son las tres partes de una fianza?', '["Insurer, insured, beneficiary", "Principal, obligee, surety", "Policyholder, agent, company", "Buyer, seller, bank"]', '["Asegurador, asegurado, beneficiario", "Principal, obligado, fiador", "Titular de póliza, agente, compañía", "Comprador, vendedor, banco"]', 1, 'The three parties are the principal (who has the obligation), the obligee (who receives the guarantee), and the surety (who provides the bond).', 'Las tres partes son el principal (quien tiene la obligación), el obligado (quien recibe la garantía) y el fiador (quien proporciona la fianza).', true, '2026-01-14 23:10:18.092074', '2026-01-14 23:10:18.092074') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('132eaf97-f315-41e1-b8f5-0cb70d28d926', 'general_lines', NULL, 'What is cyber liability insurance?', '¿Qué es el seguro de responsabilidad cibernética?', '["Auto insurance", "Coverage for losses from data breaches and cyber attacks", "Property insurance", "Life insurance"]', '["Seguro de auto", "Cobertura para pérdidas por violaciones de datos y ataques cibernéticos", "Seguro de propiedad", "Seguro de vida"]', 1, 'Cyber liability insurance covers losses resulting from data breaches, cyber attacks, and other technology-related risks.', 'El seguro de responsabilidad cibernética cubre pérdidas resultantes de violaciones de datos, ataques cibernéticos y otros riesgos relacionados con la tecnología.', true, '2026-01-14 23:10:18.217603', '2026-01-14 23:10:18.217603') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1350026e-e12e-4f23-bef8-f116dec5cff6', 'general_lines', NULL, 'What is a fidelity bond used for?', '¿Para qué se utiliza una fianza de fidelidad?', '["To cover property damage", "To protect against employee dishonesty", "To guarantee construction completion", "To provide auto coverage"]', '["Cubrir daños a la propiedad", "Proteger contra la deshonestidad de empleados", "Garantizar la finalización de construcción", "Proporcionar cobertura de auto"]', 1, 'A fidelity bond protects an employer against losses caused by dishonest acts of employees, such as theft or fraud.', 'Una fianza de fidelidad protege a un empleador contra pérdidas causadas por actos deshonestos de empleados, como robo o fraude.', true, '2026-01-14 23:10:18.098051', '2026-01-14 23:10:18.098051') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('13e83447-820d-4b7b-999c-26dd0a2b9244', 'general_lines', NULL, 'What is the liberalization clause in a property policy?', '¿Qué es la cláusula de liberalización en una póliza de propiedad?', '["A clause that increases premiums", "A clause that extends benefits if coverage is broadened during the policy term", "A clause that reduces coverage", "A cancellation clause"]', '["Una cláusula que aumenta las primas", "Una cláusula que extiende beneficios si la cobertura se amplía durante el término de la póliza", "Una cláusula que reduce la cobertura", "Una cláusula de cancelación"]', 1, 'The liberalization clause automatically extends the benefit of any coverage improvements made by the insurer during the policy period without additional premium.', 'La cláusula de liberalización extiende automáticamente el beneficio de cualquier mejora de cobertura hecha por el asegurador durante el período de la póliza sin prima adicional.', true, '2026-01-14 23:13:37.249325', '2026-01-14 23:13:37.249325') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1529258a-21a2-46e4-a71a-862c7ca779eb', 'general_lines', NULL, 'What is personal and advertising injury coverage in CGL?', '¿Qué es la cobertura de lesiones personales y publicitarias en CGL?', '["Coverage for physical injuries", "Coverage for offenses like defamation, invasion of privacy, and copyright infringement", "Auto coverage", "Property coverage"]', '["Cobertura para lesiones físicas", "Cobertura para ofensas como difamación, invasión de privacidad e infracción de derechos de autor", "Cobertura de auto", "Cobertura de propiedad"]', 1, 'Personal and advertising injury coverage protects against non-physical offenses such as libel, slander, false arrest, and copyright infringement in advertising.', 'La cobertura de lesiones personales y publicitarias protege contra ofensas no físicas como libelo, calumnia, arresto falso e infracción de derechos de autor en publicidad.', true, '2026-01-14 23:13:37.375176', '2026-01-14 23:13:37.375176') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1574fb17-6917-488d-bbef-192a667a1a62', 'general_lines', NULL, 'What is accounts receivable coverage?', '¿Qué es la cobertura de cuentas por cobrar?', '["Coverage for debt collection", "Coverage for inability to collect accounts receivable due to loss of records", "Liability coverage", "Auto coverage"]', '["Cobertura para cobro de deudas", "Cobertura por incapacidad de cobrar cuentas por cobrar debido a pérdida de registros", "Cobertura de responsabilidad", "Cobertura de auto"]', 1, 'Accounts receivable coverage pays for losses when records are destroyed and the business cannot collect money owed by customers.', 'La cobertura de cuentas por cobrar paga por pérdidas cuando los registros son destruidos y el negocio no puede cobrar dinero adeudado por clientes.', true, '2026-01-14 23:16:55.455734', '2026-01-14 23:16:55.455734') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('15ba82e4-61db-4d29-9342-f392b8ebd11b', 'general_lines', NULL, 'What is the difference between a representation and a warranty in insurance?', '¿Cuál es la diferencia entre una representación y una garantía en seguros?', '["A representation is substantially true; a warranty must be exactly true", "They are the same", "A warranty is less strict", "A representation must be exactly true"]', '["Una representación es sustancialmente verdadera; una garantía debe ser exactamente verdadera", "Son lo mismo", "Una garantía es menos estricta", "Una representación debe ser exactamente verdadera"]', 0, 'Representations need only be substantially true, while warranties are statements that must be literally and exactly true.', 'Las representaciones solo necesitan ser sustancialmente verdaderas, mientras que las garantías son declaraciones que deben ser literal y exactamente verdaderas.', true, '2026-01-14 18:28:35.704677', '2026-01-14 18:28:35.704677') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1656e932-8f2f-49d5-8ba3-39d16d6dbfd5', 'general_lines', NULL, 'What is commercial general liability limit per occurrence?', '¿Qué es el límite por ocurrencia de responsabilidad general comercial?', '["The annual maximum", "The maximum the insurer will pay for any single occurrence", "The deductible", "The premium"]', '["El máximo anual", "El máximo que el asegurador pagará por cualquier ocurrencia única", "El deducible", "La prima"]', 1, 'The per occurrence limit is the maximum amount the insurer will pay for all bodily injury and property damage arising from a single occurrence.', 'El límite por ocurrencia es la cantidad máxima que el asegurador pagará por todas las lesiones corporales y daños a la propiedad que surgen de una sola ocurrencia.', true, '2026-01-14 23:16:55.528574', '2026-01-14 23:16:55.528574') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('174a541b-7ea1-498d-96e5-9bcc67f8b5ca', 'general_lines', NULL, 'What is the Texas personal auto policy minimum liability requirement?', '¿Cuál es el requisito mínimo de responsabilidad de la póliza de auto personal de Texas?', '["$15,000/$30,000/$5,000", "$25,000/$50,000/$25,000", "$30,000/$60,000/$25,000", "$50,000/$100,000/$50,000"]', '["$15,000/$30,000/$5,000", "$25,000/$50,000/$25,000", "$30,000/$60,000/$25,000", "$50,000/$100,000/$50,000"]', 2, 'Texas requires minimum auto liability coverage of 30/60/25: $30,000 per person bodily injury, $60,000 per accident bodily injury, $25,000 property damage.', 'Texas requiere cobertura de responsabilidad de auto mínima de 30/60/25: $30,000 por persona por lesiones corporales, $60,000 por accidente por lesiones corporales, $25,000 por daños a la propiedad.', true, '2026-01-14 23:16:55.579381', '2026-01-14 23:16:55.579381') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1802c721-b1de-4937-9cb8-0f8d456bb6b0', 'general_lines', NULL, 'What is the purpose of the Texas Guaranty Association?', '¿Cuál es el propósito de la Asociación de Garantía de Texas?', '["To pay claims if an insurance company becomes insolvent", "To sell insurance", "To license agents", "To regulate premiums"]', '["Pagar reclamos si una compañía de seguros se vuelve insolvente", "Vender seguros", "Licenciar agentes", "Regular primas"]', 0, 'The Texas Guaranty Association protects policyholders by paying covered claims when an insurance company becomes insolvent.', 'La Asociación de Garantía de Texas protege a los asegurados pagando reclamos cubiertos cuando una compañía de seguros se vuelve insolvente.', true, '2026-01-14 18:28:35.681635', '2026-01-14 18:28:35.681635') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('184ab0d7-8871-46e1-81c7-5299275873d5', 'general_lines', NULL, 'What is the standard fire policy?', '¿Qué es la póliza estándar contra incendios?', '["A modern policy form", "A historical policy form providing basic fire coverage that has been replaced by newer forms", "A life insurance policy", "An auto policy"]', '["Un formulario de póliza moderno", "Un formulario de póliza histórico que proporciona cobertura básica contra incendios que ha sido reemplazado por formularios más nuevos", "Una póliza de seguro de vida", "Una póliza de auto"]', 1, 'The standard fire policy was a basic property insurance form that has largely been replaced by more comprehensive commercial property forms.', 'La póliza estándar contra incendios fue un formulario básico de seguro de propiedad que ha sido reemplazado en gran parte por formularios de propiedad comercial más completos.', true, '2026-01-14 23:23:21.008444', '2026-01-14 23:23:21.008444') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1932bc6a-d972-41ac-889b-9822ff5c21f1', 'general_lines', NULL, 'What is the expected or intended injury exclusion?', '¿Qué es la exclusión de lesión esperada o intencional?', '["Coverage for intentional acts", "An exclusion for injury the insured expected or intended", "A premium calculation", "An endorsement"]', '["Cobertura para actos intencionales", "Una exclusión para lesiones que el asegurado esperaba o pretendía", "Un cálculo de prima", "Un endoso"]', 1, 'The expected or intended injury exclusion eliminates coverage for bodily injury or property damage that the insured expected or intended to cause.', 'La exclusión de lesión esperada o intencional elimina la cobertura para lesiones corporales o daños a la propiedad que el asegurado esperaba o pretendía causar.', true, '2026-01-14 23:13:37.392683', '2026-01-14 23:13:37.392683') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1a844ba0-c72f-4208-afee-62867e2ea6ea', 'general_lines', NULL, 'What is defense cost coverage in liability insurance?', '¿Qué es la cobertura de costos de defensa en el seguro de responsabilidad?', '["Military insurance", "Coverage for legal costs to defend against covered claims", "Property coverage", "Auto coverage"]', '["Seguro militar", "Cobertura para costos legales de defender contra reclamos cubiertos", "Cobertura de propiedad", "Cobertura de auto"]', 1, 'Defense cost coverage pays for attorneys'' fees, court costs, and other expenses to defend against claims or lawsuits covered by the liability policy.', 'La cobertura de costos de defensa paga por honorarios de abogados, costos judiciales y otros gastos para defender contra reclamos o demandas cubiertos por la póliza de responsabilidad.', true, '2026-01-14 23:16:55.539196', '2026-01-14 23:16:55.539196') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1b202a1e-091b-44ab-bea4-5e57416ac3f7', 'general_lines', NULL, 'What is extra expense coverage?', '¿Qué es la cobertura de gastos extra?', '["Coverage for luxury items", "Coverage for additional costs to continue operations after a covered loss", "Premium payments", "Deductible expenses"]', '["Cobertura para artículos de lujo", "Cobertura para costos adicionales para continuar operaciones después de una pérdida cubierta", "Pagos de prima", "Gastos de deducible"]', 1, 'Extra expense coverage pays for additional costs necessary to continue business operations while property is being repaired after a covered loss.', 'La cobertura de gastos extra paga costos adicionales necesarios para continuar las operaciones del negocio mientras la propiedad está siendo reparada después de una pérdida cubierta.', true, '2026-01-14 23:16:55.415083', '2026-01-14 23:16:55.415083') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1d336e47-c478-48a5-932b-35ca42411446', 'general_lines', NULL, 'What is the principle of indemnity?', '¿Qué es el principio de indemnización?', '["To make the insured wealthy", "To restore the insured to the same financial position as before the loss", "To pay more than the loss", "To deny all claims"]', '["Enriquecer al asegurado", "Restaurar al asegurado a la misma posición financiera que antes de la pérdida", "Pagar más que la pérdida", "Denegar todos los reclamos"]', 1, 'The principle of indemnity ensures the insured is restored to their pre-loss financial condition, not better or worse.', 'El principio de indemnización asegura que el asegurado sea restaurado a su condición financiera previa a la pérdida, no mejor ni peor.', true, '2026-01-14 23:13:37.32718', '2026-01-14 23:13:37.32718') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('23816fcf-1c77-401b-bc87-a30afa448f3c', 'general_lines', NULL, 'What is premises liability?', '¿Qué es la responsabilidad por instalaciones?', '["Product liability", "Liability for injuries occurring on property owned or occupied by the insured", "Auto liability", "Professional liability"]', '["Responsabilidad por productos", "Responsabilidad por lesiones que ocurren en propiedad poseída u ocupada por el asegurado", "Responsabilidad de auto", "Responsabilidad profesional"]', 1, 'Premises liability covers claims for bodily injury or property damage occurring on the insured''s premises due to a dangerous condition.', 'La responsabilidad por instalaciones cubre reclamos por lesiones corporales o daños a la propiedad que ocurren en las instalaciones del asegurado debido a una condición peligrosa.', true, '2026-01-14 23:13:37.378919', '2026-01-14 23:13:37.378919') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2478304e-0b00-4307-9385-ee151083198b', 'general_lines', NULL, 'What is the purpose of loss control services?', '¿Cuál es el propósito de los servicios de control de pérdidas?', '["To pay claims faster", "To help insureds identify and reduce hazards that could lead to losses", "To increase premiums", "To deny claims"]', '["Pagar reclamos más rápido", "Ayudar a los asegurados a identificar y reducir peligros que podrían llevar a pérdidas", "Aumentar las primas", "Denegar reclamos"]', 1, 'Loss control services help insureds identify hazards and implement measures to prevent or reduce losses, benefiting both the insured and insurer.', 'Los servicios de control de pérdidas ayudan a los asegurados a identificar peligros e implementar medidas para prevenir o reducir pérdidas, beneficiando tanto al asegurado como al asegurador.', true, '2026-01-14 23:16:55.58222', '2026-01-14 23:16:55.58222') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('274cf9a1-3967-43c8-8a7f-ab69f5df3682', 'general_lines', NULL, 'What is ocean marine insurance?', '¿Qué es el seguro marítimo oceánico?', '["Insurance for beach property", "Coverage for ships, cargo, and marine-related liabilities", "Flood insurance", "Life insurance"]', '["Seguro para propiedad de playa", "Cobertura para barcos, carga y responsabilidades relacionadas con el mar", "Seguro contra inundaciones", "Seguro de vida"]', 1, 'Ocean marine insurance covers ships, cargo, and liabilities associated with ocean-going vessels and international shipping.', 'El seguro marítimo oceánico cubre barcos, carga y responsabilidades asociadas con embarcaciones oceánicas y envío internacional.', true, '2026-01-14 23:16:55.478023', '2026-01-14 23:16:55.478023') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('281224aa-7384-43b7-9ec2-a0783c33427b', 'general_lines', NULL, 'What is surplus lines insurance?', '¿Qué es el seguro de líneas excedentes?', '["Insurance purchased from non-admitted insurers for risks the standard market won''t cover", "Standard insurance", "Life insurance", "Health insurance"]', '["Seguro comprado de aseguradores no admitidos para riesgos que el mercado estándar no cubrirá", "Seguro estándar", "Seguro de vida", "Seguro de salud"]', 0, 'Surplus lines insurance is coverage from non-admitted insurers for unusual risks that standard insurance companies won''t insure.', 'El seguro de líneas excedentes es cobertura de aseguradores no admitidos para riesgos inusuales que las compañías de seguros estándar no asegurarán.', true, '2026-01-14 18:28:35.687218', '2026-01-14 18:28:35.687218') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('292e473b-f01b-4804-a91b-c8e8e6b329b4', 'general_lines', NULL, 'What is utility services coverage?', '¿Qué es la cobertura de servicios públicos?', '["Coverage for utility company property", "Coverage for losses caused by interruption of utility services", "Life insurance", "Auto coverage"]', '["Cobertura para propiedad de compañías de servicios públicos", "Cobertura por pérdidas causadas por interrupción de servicios públicos", "Seguro de vida", "Cobertura de auto"]', 1, 'Utility services coverage pays for losses resulting from the interruption of utility services (power, water, communications) caused by damage to utility property.', 'La cobertura de servicios públicos paga por pérdidas resultantes de la interrupción de servicios públicos (electricidad, agua, comunicaciones) causada por daños a la propiedad de servicios públicos.', true, '2026-01-14 23:16:55.438054', '2026-01-14 23:16:55.438054') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('29c4a87b-729a-46a9-9072-4180f4a38af4', 'general_lines', NULL, 'What does the term ''aggregate limit'' mean in liability insurance?', '¿Qué significa el término ''límite agregado'' en el seguro de responsabilidad?', '["The per-claim limit", "The maximum amount the insurer will pay for all claims during the policy period", "The deductible amount", "The minimum coverage required"]', '["El límite por reclamo", "La cantidad máxima que el asegurador pagará por todos los reclamos durante el período de la póliza", "El monto del deducible", "La cobertura mínima requerida"]', 1, 'The aggregate limit is the maximum total amount the insurer will pay for all covered claims during a policy period.', 'El límite agregado es la cantidad total máxima que el asegurador pagará por todos los reclamos cubiertos durante un período de póliza.', true, '2026-01-14 23:13:37.252928', '2026-01-14 23:13:37.252928') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2b4617e6-21bb-4db3-a2cf-9b00582f935a', 'general_lines', NULL, 'What is an insurance binder?', '¿Qué es un binder de seguro?', '["Temporary proof of insurance until the policy is issued", "A permanent policy", "A claim form", "A cancellation notice"]', '["Prueba temporal de seguro hasta que se emita la póliza", "Una póliza permanente", "Un formulario de reclamo", "Un aviso de cancelación"]', 0, 'A binder is a temporary insurance contract providing immediate coverage until the formal policy is issued.', 'Un binder es un contrato de seguro temporal que proporciona cobertura inmediata hasta que se emita la póliza formal.', true, '2026-01-14 18:28:35.684469', '2026-01-14 18:28:35.684469') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2ce52f5e-73f5-465e-a629-ab035e36fa02', 'general_lines', NULL, 'What is earthquake coverage?', '¿Qué es la cobertura contra terremotos?', '["Included in all policies", "Coverage for earthquake damage typically requiring a separate policy or endorsement", "Life insurance", "Auto coverage"]', '["Incluida en todas las pólizas", "Cobertura para daños por terremotos típicamente requiriendo una póliza separada o endoso", "Seguro de vida", "Cobertura de auto"]', 1, 'Earthquake coverage protects against earthquake damage and is usually excluded from standard property policies, requiring a separate policy or endorsement.', 'La cobertura contra terremotos protege contra daños por terremotos y usualmente está excluida de las pólizas de propiedad estándar, requiriendo una póliza o endoso separado.', true, '2026-01-14 23:23:21.014709', '2026-01-14 23:23:21.014709') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2ec121f1-7299-4d48-acea-b3fb95d8dafc', 'general_lines', NULL, 'What is liquor liability insurance?', '¿Qué es el seguro de responsabilidad por licor?', '["Insurance for liquor stores", "Coverage for claims arising from the sale or service of alcohol", "Property coverage", "Auto coverage"]', '["Seguro para tiendas de licores", "Cobertura para reclamos que surgen de la venta o servicio de alcohol", "Cobertura de propiedad", "Cobertura de auto"]', 1, 'Liquor liability insurance covers claims arising from injuries or damages caused by intoxicated persons who were served alcohol by the insured.', 'El seguro de responsabilidad por licor cubre reclamos que surgen de lesiones o daños causados por personas intoxicadas a quienes el asegurado sirvió alcohol.', true, '2026-01-14 23:10:18.249966', '2026-01-14 23:10:18.249966') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2f6504da-289c-4304-a799-0edb683830b2', 'general_lines', NULL, 'What is morale hazard?', '¿Qué es el peligro de moralidad?', '["Intentional loss causing", "Carelessness or indifference to loss because of insurance", "A physical condition", "An exclusion"]', '["Causar pérdidas intencionales", "Descuido o indiferencia a la pérdida debido al seguro", "Una condición física", "Una exclusión"]', 1, 'Morale hazard is unintentional carelessness or indifference to preventing losses because insurance will cover the damage.', 'El peligro de moralidad es el descuido no intencional o la indiferencia hacia la prevención de pérdidas porque el seguro cubrirá el daño.', true, '2026-01-14 23:23:20.931209', '2026-01-14 23:23:20.931209') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2f8f8254-4dd6-4aca-bfbd-81974ace8cd3', 'general_lines', NULL, 'What is an admitted insurance company?', '¿Qué es una compañía de seguros admitida?', '["A company licensed by the state to sell insurance", "An unlicensed company", "A surplus lines company", "A foreign company"]', '["Una compañía licenciada por el estado para vender seguros", "Una compañía sin licencia", "Una compañía de líneas excedentes", "Una compañía extranjera"]', 0, 'An admitted insurer is an insurance company that has been licensed by the state insurance department to conduct business in that state.', 'Un asegurador admitido es una compañía de seguros que ha sido licenciada por el departamento de seguros del estado para conducir negocios en ese estado.', true, '2026-01-14 18:28:35.701881', '2026-01-14 18:28:35.701881') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('306d0118-d22f-45ad-91ba-6288d4a60921', 'general_lines', NULL, 'What is a warranty in an insurance contract?', '¿Qué es una garantía en un contrato de seguro?', '["A type of coverage", "A statement or promise by the insured that must be strictly true for coverage to apply", "A premium discount", "An exclusion"]', '["Un tipo de cobertura", "Una declaración o promesa del asegurado que debe ser estrictamente verdadera para que se aplique la cobertura", "Un descuento de prima", "Una exclusión"]', 1, 'A warranty is a statement or promise made by the insured that must be strictly true, and a breach may void the policy.', 'Una garantía es una declaración o promesa hecha por el asegurado que debe ser estrictamente verdadera, y una violación puede anular la póliza.', true, '2026-01-14 23:13:37.34261', '2026-01-14 23:13:37.34261') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('31d7c589-0718-4702-903e-d0d142aadb0e', 'general_lines', NULL, 'What is aviation insurance?', '¿Qué es el seguro de aviación?', '["Travel insurance", "Coverage for aircraft hull damage and aviation-related liabilities", "Auto insurance", "Life insurance"]', '["Seguro de viaje", "Cobertura para daños al casco de aeronaves y responsabilidades relacionadas con la aviación", "Seguro de auto", "Seguro de vida"]', 1, 'Aviation insurance covers aircraft physical damage (hull coverage), liability for passenger injuries and property damage, and other aviation-related risks.', 'El seguro de aviación cubre daños físicos a aeronaves (cobertura de casco), responsabilidad por lesiones a pasajeros y daños a la propiedad, y otros riesgos relacionados con la aviación.', true, '2026-01-14 23:16:55.496714', '2026-01-14 23:16:55.496714') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('326ff389-d243-44ca-bc48-35bc27ef499d', 'general_lines', NULL, 'What is an independent adjuster?', '¿Qué es un ajustador independiente?', '["An insurance company employee", "A contract adjuster hired by insurers to handle claims", "A public adjuster", "A government adjuster"]', '["Un empleado de la compañía de seguros", "Un ajustador contratado por aseguradores para manejar reclamos", "Un ajustador público", "Un ajustador del gobierno"]', 1, 'An independent adjuster is a contractor hired by insurance companies to investigate and settle claims, not employed directly by any insurer.', 'Un ajustador independiente es un contratista contratado por compañías de seguros para investigar y liquidar reclamos, no empleado directamente por ningún asegurador.', true, '2026-01-14 23:23:20.986827', '2026-01-14 23:23:20.986827') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('32781c6b-4b13-4fff-b884-bbf2303a24d6', 'general_lines', NULL, 'What is a payment bond?', '¿Qué es una fianza de pago?', '["A premium payment plan", "A guarantee that subcontractors and suppliers will be paid", "A type of deductible", "An endorsement"]', '["Un plan de pago de prima", "Una garantía de que los subcontratistas y proveedores serán pagados", "Un tipo de deducible", "Un endoso"]', 1, 'A payment bond guarantees that the contractor will pay subcontractors, laborers, and suppliers for work performed on a project.', 'Una fianza de pago garantiza que el contratista pagará a los subcontratistas, trabajadores y proveedores por el trabajo realizado en un proyecto.', true, '2026-01-14 23:10:18.151559', '2026-01-14 23:10:18.151559') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('339fd630-7058-432b-b0cc-455b44f58a3e', 'general_lines', NULL, 'What is a waiver of subrogation?', '¿Qué es una renuncia de subrogación?', '["A type of coverage", "An agreement where the insurer gives up the right to recover from a third party", "A premium discount", "A deductible waiver"]', '["Un tipo de cobertura", "Un acuerdo donde el asegurador renuncia al derecho de recuperar de un tercero", "Un descuento de prima", "Una exención de deducible"]', 1, 'A waiver of subrogation is an endorsement where the insurer agrees not to pursue recovery from a specific third party after paying a claim.', 'Una renuncia de subrogación es un endoso donde el asegurador acepta no buscar recuperación de un tercero específico después de pagar un reclamo.', true, '2026-01-14 23:13:37.220226', '2026-01-14 23:13:37.220226') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('33ae0a7c-e066-40fb-b430-405760560681', 'general_lines', NULL, 'What is a public official bond?', '¿Qué es una fianza de funcionario público?', '["A private bond", "A bond guaranteeing honest performance by elected or appointed officials", "A bid bond", "A payment bond"]', '["Una fianza privada", "Una fianza que garantiza el desempeño honesto de funcionarios electos o nombrados", "Una fianza de licitación", "Una fianza de pago"]', 1, 'A public official bond guarantees that elected or appointed public officials will faithfully and honestly perform their duties.', 'Una fianza de funcionario público garantiza que los funcionarios públicos electos o nombrados desempeñarán sus deberes fielmente y honestamente.', true, '2026-01-14 23:16:55.516672', '2026-01-14 23:16:55.516672') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('33d66fe9-9e33-46b8-9b81-347c4b2f868e', 'general_lines', NULL, 'What is flood insurance typically excluded from?', '¿De qué está típicamente excluido el seguro contra inundaciones?', '["Flood policies", "Standard property insurance policies, requiring separate coverage", "Life insurance", "Auto insurance"]', '["Pólizas contra inundaciones", "Pólizas de seguro de propiedad estándar, requiriendo cobertura separada", "Seguro de vida", "Seguro de auto"]', 1, 'Flood is typically excluded from standard property policies and must be purchased separately through the NFIP or private flood insurers.', 'Las inundaciones típicamente están excluidas de las pólizas de propiedad estándar y deben comprarse por separado a través del NFIP o aseguradores privados de inundaciones.', true, '2026-01-14 23:23:21.012015', '2026-01-14 23:23:21.012015') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('34517d00-48f1-483b-be6a-09ea66d6c706', 'general_lines', NULL, 'What is the difference between primary and excess insurance?', '¿Cuál es la diferencia entre seguro primario y excedente?', '["No difference", "Primary pays first; excess pays after primary limits are exhausted", "Excess always pays first", "Primary covers property only"]', '["Sin diferencia", "El primario paga primero; el excedente paga después de que se agoten los límites primarios", "El excedente siempre paga primero", "El primario solo cubre propiedad"]', 1, 'Primary insurance pays claims first up to its limits, while excess insurance only pays after the primary policy''s limits are exhausted.', 'El seguro primario paga reclamos primero hasta sus límites, mientras que el seguro excedente solo paga después de que se agoten los límites de la póliza primaria.', true, '2026-01-14 23:10:18.23764', '2026-01-14 23:10:18.23764') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('349d75bb-30f3-4fd4-b538-bf00b0557d90', 'general_lines', NULL, 'What is the difference between replacement cost and actual cash value?', '¿Cuál es la diferencia entre costo de reemplazo y valor real en efectivo?', '["No difference", "Replacement cost pays full replacement; actual cash value deducts depreciation", "Actual cash value pays more", "Replacement cost includes market value"]', '["Sin diferencia", "Costo de reemplazo paga el reemplazo completo; valor real en efectivo deduce depreciación", "Valor real en efectivo paga más", "Costo de reemplazo incluye valor de mercado"]', 1, 'Replacement cost pays to replace or repair property without deducting for depreciation, while actual cash value deducts depreciation from the replacement cost.', 'El costo de reemplazo paga para reemplazar o reparar la propiedad sin deducir la depreciación, mientras que el valor real en efectivo deduce la depreciación del costo de reemplazo.', true, '2026-01-14 23:10:18.167086', '2026-01-14 23:10:18.167086') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('34f5a539-05c2-47cc-a3cd-ced989dd6f2c', 'general_lines', NULL, 'What is the difference between scheduled and blanket coverage?', '¿Cuál es la diferencia entre cobertura programada y general?', '["No difference", "Scheduled lists specific items with values; blanket covers multiple items under one limit", "Blanket is always more expensive", "Scheduled has no limits"]', '["Sin diferencia", "Programada lista artículos específicos con valores; general cubre múltiples artículos bajo un límite", "General siempre es más cara", "Programada no tiene límites"]', 1, 'Scheduled coverage lists specific items with individual values, while blanket coverage applies a single limit to multiple items or locations.', 'La cobertura programada lista artículos específicos con valores individuales, mientras que la cobertura general aplica un solo límite a múltiples artículos o ubicaciones.', true, '2026-01-14 23:16:55.468079', '2026-01-14 23:16:55.468079') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('34ffecc4-c9aa-4d0f-b099-72fb3ae77dbf', 'general_lines', NULL, 'What is General Lines insurance in Texas?', '¿Qué es el seguro de Líneas Generales en Texas?', '["Only life insurance", "Property, casualty, surety, and related coverages", "Only health insurance", "Only auto insurance"]', '["Solo seguro de vida", "Propiedad, accidentes, fianzas y coberturas relacionadas", "Solo seguro de salud", "Solo seguro de auto"]', 1, 'General Lines insurance in Texas includes property, casualty, surety bonds, and related lines of coverage.', 'El seguro de Líneas Generales en Texas incluye propiedad, accidentes, fianzas y líneas de cobertura relacionadas.', true, '2026-01-14 23:10:18.076779', '2026-01-14 23:10:18.076779') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('35c8b8bd-e41b-4859-8946-d7d7fad1323a', 'general_lines', NULL, 'What is a loading in insurance premiums?', '¿Qué es una carga en las primas de seguro?', '["Expected losses", "The amount added to pure premium for expenses, contingencies, and profit", "A discount", "A deductible"]', '["Pérdidas esperadas", "La cantidad agregada a la prima pura para gastos, contingencias y ganancia", "Un descuento", "Un deducible"]', 1, 'Loading is the amount added to the pure premium to cover operating expenses, contingencies, and provide a profit margin.', 'La carga es la cantidad agregada a la prima pura para cubrir gastos operativos, contingencias y proporcionar un margen de ganancia.', true, '2026-01-14 23:23:20.914276', '2026-01-14 23:23:20.914276') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('364a43f2-14d4-482b-9364-d1d70281511e', 'general_lines', NULL, 'What is crime insurance?', '¿Qué es el seguro contra crímenes?', '["Insurance for criminals", "Coverage for losses due to criminal acts such as theft, fraud, and forgery", "Liability insurance", "Life insurance"]', '["Seguro para criminales", "Cobertura para pérdidas debido a actos criminales como robo, fraude y falsificación", "Seguro de responsabilidad", "Seguro de vida"]', 1, 'Crime insurance covers losses resulting from criminal acts including employee theft, forgery, robbery, burglary, and computer fraud.', 'El seguro contra crímenes cubre pérdidas resultantes de actos criminales incluyendo robo de empleados, falsificación, robo con violencia, allanamiento y fraude informático.', true, '2026-01-14 23:10:18.205907', '2026-01-14 23:10:18.205907') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('373ff501-47e9-4d79-8fba-f018ef742b27', 'general_lines', NULL, 'What is a court bond?', '¿Qué es una fianza judicial?', '["A performance bond", "A bond required in judicial proceedings to guarantee performance of obligations", "A bid bond", "An employee bond"]', '["Una fianza de cumplimiento", "Una fianza requerida en procedimientos judiciales para garantizar el cumplimiento de obligaciones", "Una fianza de licitación", "Una fianza de empleado"]', 1, 'A court bond is required in judicial proceedings and guarantees that a party will fulfill certain obligations ordered by the court.', 'Una fianza judicial es requerida en procedimientos judiciales y garantiza que una parte cumplirá ciertas obligaciones ordenadas por el tribunal.', true, '2026-01-14 23:16:55.50536', '2026-01-14 23:16:55.50536') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3bcfb10f-3721-499a-be5b-afdf3f13d9dd', 'general_lines', NULL, 'What is an experience modification factor in workers'' compensation?', '¿Qué es un factor de modificación de experiencia en compensación de trabajadores?', '["A type of coverage", "A multiplier that adjusts premiums based on the employer''s claims history", "An exclusion", "A deductible"]', '["Un tipo de cobertura", "Un multiplicador que ajusta las primas basado en el historial de reclamos del empleador", "Una exclusión", "Un deducible"]', 1, 'The experience modification factor adjusts workers'' compensation premiums based on an employer''s past claims experience compared to similar employers.', 'El factor de modificación de experiencia ajusta las primas de compensación de trabajadores basado en la experiencia de reclamos pasados del empleador comparado con empleadores similares.', true, '2026-01-14 23:10:18.196682', '2026-01-14 23:10:18.196682') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3e17da90-2e7c-4826-a57b-800f6c2cef4b', 'general_lines', NULL, 'What is a commercial package policy (CPP)?', '¿Qué es una póliza de paquete comercial (CPP)?', '["A policy for shipping packages", "A modular policy combining multiple commercial coverages", "A personal insurance policy", "A life insurance policy"]', '["Una póliza para enviar paquetes", "Una póliza modular que combina múltiples coberturas comerciales", "Una póliza de seguro personal", "Una póliza de seguro de vida"]', 1, 'A CPP is a modular policy that combines two or more commercial coverage parts, such as property, liability, and crime, into a single policy.', 'Una CPP es una póliza modular que combina dos o más partes de cobertura comercial, como propiedad, responsabilidad y crímenes, en una sola póliza.', true, '2026-01-14 23:10:18.209601', '2026-01-14 23:10:18.209601') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3e48a5f7-b6d7-4096-8c25-7fc163da7464', 'general_lines', NULL, 'What is employers'' liability insurance?', '¿Qué es el seguro de responsabilidad del empleador?', '["The same as workers'' compensation", "Coverage for lawsuits by injured employees not covered by workers'' compensation", "Property insurance", "Auto insurance"]', '["Lo mismo que compensación de trabajadores", "Cobertura para demandas por empleados lesionados no cubiertas por compensación de trabajadores", "Seguro de propiedad", "Seguro de auto"]', 1, 'Employers'' liability insurance covers claims by employees or their heirs that fall outside the workers'' compensation system, such as third-party-over claims.', 'El seguro de responsabilidad del empleador cubre reclamos de empleados o sus herederos que caen fuera del sistema de compensación de trabajadores, como reclamos de terceros.', true, '2026-01-14 23:10:18.199888', '2026-01-14 23:10:18.199888') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3eaef517-018b-4df0-b5a1-1f0fd90c4910', 'general_lines', NULL, 'What is the care, custody, or control exclusion?', '¿Qué es la exclusión de cuidado, custodia o control?', '["Coverage for property in your care", "An exclusion for property in the insured''s care, custody, or control", "A premium discount", "An endorsement"]', '["Cobertura para propiedad bajo su cuidado", "Una exclusión para propiedad bajo el cuidado, custodia o control del asegurado", "Un descuento de prima", "Un endoso"]', 1, 'This exclusion eliminates liability coverage for damage to property in the insured''s care, custody, or control, which should be covered by property or bailee coverage.', 'Esta exclusión elimina la cobertura de responsabilidad por daños a la propiedad bajo el cuidado, custodia o control del asegurado, que debería estar cubierta por cobertura de propiedad o depositario.', true, '2026-01-14 23:13:37.396031', '2026-01-14 23:13:37.396031') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3f35bafa-3835-439b-b607-a27ed2e9fb6f', 'general_lines', NULL, 'What is a conditional contract in insurance?', '¿Qué es un contrato condicional en seguros?', '["A contract where the insurer''s obligation depends on certain conditions being met", "An unconditional contract", "A loan agreement", "A lease agreement"]', '["Un contrato donde la obligación del asegurador depende de que se cumplan ciertas condiciones", "Un contrato incondicional", "Un acuerdo de préstamo", "Un contrato de arrendamiento"]', 0, 'Insurance is a conditional contract because the insurer''s obligation to pay depends on conditions like paying premiums and filing claims properly.', 'El seguro es un contrato condicional porque la obligación del asegurador de pagar depende de condiciones como pagar primas y presentar reclamos correctamente.', true, '2026-01-14 18:28:35.713072', '2026-01-14 18:28:35.713072') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3f69707a-e81d-4e1e-970e-c7becac878df', 'general_lines', NULL, 'What is a pure premium?', '¿Qué es una prima pura?', '["The total premium charged", "The portion of premium needed to pay expected losses", "The agent''s commission", "The profit margin"]', '["La prima total cobrada", "La porción de la prima necesaria para pagar las pérdidas esperadas", "La comisión del agente", "El margen de ganancia"]', 1, 'The pure premium is the portion of the premium that covers expected losses, before adding expenses and profit loading.', 'La prima pura es la porción de la prima que cubre las pérdidas esperadas, antes de agregar gastos y carga de ganancia.', true, '2026-01-14 23:23:20.906464', '2026-01-14 23:23:20.906464') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('40870fbe-42dd-4718-99e1-9eb3aa065bf4', 'general_lines', NULL, 'What is the National Flood Insurance Program (NFIP)?', '¿Qué es el Programa Nacional de Seguro contra Inundaciones (NFIP)?', '["A private insurance program", "A federal program providing flood insurance in participating communities", "A state program", "An excess flood program"]', '["Un programa de seguro privado", "Un programa federal que proporciona seguro contra inundaciones en comunidades participantes", "Un programa estatal", "Un programa de inundación excedente"]', 1, 'The NFIP is a federal program administered by FEMA that provides flood insurance to property owners in participating communities.', 'El NFIP es un programa federal administrado por FEMA que proporciona seguro contra inundaciones a propietarios de propiedades en comunidades participantes.', true, '2026-01-14 23:13:37.310862', '2026-01-14 23:13:37.310862') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('409a4859-2381-4564-9117-d2403bd8e44b', 'general_lines', NULL, 'What is churning in insurance?', '¿Qué es el ''churning'' en seguros?', '["A type of coverage", "Excessive replacement of policies to generate commissions", "A premium payment method", "A claims process"]', '["Un tipo de cobertura", "Reemplazo excesivo de pólizas para generar comisiones", "Un método de pago de prima", "Un proceso de reclamos"]', 1, 'Churning is the unethical practice of repeatedly replacing insurance policies primarily to generate commission income for the agent.', 'El churning es la práctica poco ética de reemplazar repetidamente pólizas de seguro principalmente para generar ingresos por comisiones para el agente.', true, '2026-01-14 23:13:37.283557', '2026-01-14 23:13:37.283557') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('42a5bdb0-8dd8-4d91-aca0-3560d1be984a', 'general_lines', NULL, 'What is underwriting in insurance?', '¿Qué es la suscripción en seguros?', '["Selling insurance policies", "The process of evaluating risks and determining coverage terms and pricing", "Paying claims", "Processing applications"]', '["Vender pólizas de seguro", "El proceso de evaluar riesgos y determinar términos de cobertura y precios", "Pagar reclamos", "Procesar solicitudes"]', 1, 'Underwriting is the process of evaluating insurance applications, assessing risk, and determining whether to accept the risk and at what price and terms.', 'La suscripción es el proceso de evaluar solicitudes de seguro, evaluar riesgos y determinar si aceptar el riesgo y a qué precio y términos.', true, '2026-01-14 23:23:20.887831', '2026-01-14 23:23:20.887831') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('42acbdf6-5b14-4236-90eb-04349d7dfd0d', 'general_lines', NULL, 'What is a motor carrier bond?', '¿Qué es una fianza de transportista motorizado?', '["Auto insurance", "A bond required for trucking companies to guarantee cargo and liability obligations", "A personal bond", "A life insurance bond"]', '["Seguro de auto", "Una fianza requerida para compañías de camiones para garantizar obligaciones de carga y responsabilidad", "Una fianza personal", "Una fianza de seguro de vida"]', 1, 'A motor carrier bond is required by federal and state regulations for trucking companies to guarantee payment for cargo damage and liability claims.', 'Una fianza de transportista motorizado es requerida por regulaciones federales y estatales para compañías de camiones para garantizar el pago por daños a la carga y reclamos de responsabilidad.', true, '2026-01-14 23:16:55.525169', '2026-01-14 23:16:55.525169') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('458048df-a31e-43d0-90f9-d65f9cd95a70', 'general_lines', NULL, 'What fiduciary duty does an agent owe to their clients?', '¿Qué deber fiduciario debe un agente a sus clientes?', '["No duties", "A duty of loyalty, care, and to act in the client''s best interest", "Only to sell policies", "Only to collect premiums"]', '["Sin deberes", "Un deber de lealtad, cuidado y actuar en el mejor interés del cliente", "Solo vender pólizas", "Solo cobrar primas"]', 1, 'Agents owe fiduciary duties including loyalty, care, good faith, and the obligation to act in the best interest of their clients.', 'Los agentes deben deberes fiduciarios incluyendo lealtad, cuidado, buena fe y la obligación de actuar en el mejor interés de sus clientes.', true, '2026-01-14 23:23:21.045256', '2026-01-14 23:23:21.045256') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('46cb0847-e4bb-4e2f-a6e1-8ab572f0d754', 'general_lines', NULL, 'What is the difference between comprehensive and collision coverage?', '¿Cuál es la diferencia entre cobertura comprensiva y de colisión?', '["No difference", "Comprehensive covers non-collision losses; collision covers collision with objects", "Collision is always cheaper", "Comprehensive only covers theft"]', '["Sin diferencia", "Comprensiva cubre pérdidas sin colisión; colisión cubre colisión con objetos", "Colisión siempre es más barata", "Comprensiva solo cubre robo"]', 1, 'Comprehensive covers losses other than collision (theft, fire, vandalism, weather), while collision covers damage from impact with another object.', 'Comprensiva cubre pérdidas que no son de colisión (robo, incendio, vandalismo, clima), mientras que colisión cubre daños por impacto con otro objeto.', true, '2026-01-14 23:16:55.566971', '2026-01-14 23:16:55.566971') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('46e8c2f0-a795-45a3-832d-3a3c4a04891d', 'general_lines', NULL, 'What is a physical hazard?', '¿Qué es un peligro físico?', '["A moral condition", "A physical condition that increases the likelihood or severity of loss", "An exclusion", "A premium"]', '["Una condición moral", "Una condición física que aumenta la probabilidad o severidad de pérdida", "Una exclusión", "Una prima"]', 1, 'A physical hazard is a tangible condition that increases the chance of loss, such as faulty wiring, icy sidewalks, or defective equipment.', 'Un peligro físico es una condición tangible que aumenta la probabilidad de pérdida, como cableado defectuoso, aceras heladas o equipo defectuoso.', true, '2026-01-14 23:23:20.934989', '2026-01-14 23:23:20.934989') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('48ca7de1-8b16-4a5b-9a55-65c0a493676a', 'general_lines', NULL, 'What is a valued policy?', '¿Qué es una póliza valorada?', '["A policy with no value", "A policy that pays a predetermined amount in case of total loss", "A liability policy", "A term policy"]', '["Una póliza sin valor", "Una póliza que paga una cantidad predeterminada en caso de pérdida total", "Una póliza de responsabilidad", "Una póliza a término"]', 1, 'A valued policy pays a predetermined amount stated in the policy in the event of a total loss, regardless of actual cash value.', 'Una póliza valorada paga una cantidad predeterminada indicada en la póliza en caso de una pérdida total, independientemente del valor real en efectivo.', true, '2026-01-14 23:13:37.35402', '2026-01-14 23:13:37.35402') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('49f5d4ea-3586-44ec-8fb7-2d0249cf3aea', 'general_lines', NULL, 'What is an appraisal clause?', '¿Qué es una cláusula de tasación?', '["A premium calculation method", "A policy provision for resolving disputes over the value of a loss", "A coverage limit", "An exclusion"]', '["Un método de cálculo de prima", "Una disposición de póliza para resolver disputas sobre el valor de una pérdida", "Un límite de cobertura", "Una exclusión"]', 1, 'The appraisal clause provides a process to resolve disputes over the amount of a loss, where each party selects an appraiser and they choose an umpire.', 'La cláusula de tasación proporciona un proceso para resolver disputas sobre el monto de una pérdida, donde cada parte selecciona un tasador y ellos eligen un árbitro.', true, '2026-01-14 23:23:20.992045', '2026-01-14 23:23:20.992045') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4b6f02d9-081e-4021-bc50-12979d5bde6b', 'general_lines', NULL, 'What is the continuing education requirement for Texas insurance agents?', '¿Cuál es el requisito de educación continua para agentes de seguros de Texas?', '["No requirement", "Completing required continuing education hours to maintain licensure", "Only one course ever", "Only for new agents"]', '["Sin requisito", "Completar las horas de educación continua requeridas para mantener la licencia", "Solo un curso", "Solo para nuevos agentes"]', 1, 'Texas requires licensed agents to complete continuing education hours every licensing period, including ethics courses, to maintain their license.', 'Texas requiere que los agentes con licencia completen horas de educación continua cada período de licencia, incluyendo cursos de ética, para mantener su licencia.', true, '2026-01-14 23:23:21.039364', '2026-01-14 23:23:21.039364') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4c7e503c-01e0-4bfc-9cc2-18da3803a700', 'general_lines', NULL, 'What is risk pooling?', '¿Qué es la agrupación de riesgos?', '["Avoiding all risks", "Combining many similar risks to spread the cost of losses among all members", "Transferring all risks", "Eliminating risks"]', '["Evitar todos los riesgos", "Combinar muchos riesgos similares para distribuir el costo de las pérdidas entre todos los miembros", "Transferir todos los riesgos", "Eliminar riesgos"]', 1, 'Risk pooling combines many similar exposures to spread the cost of losses among the entire group, making individual losses more predictable.', 'La agrupación de riesgos combina muchas exposiciones similares para distribuir el costo de las pérdidas entre todo el grupo, haciendo las pérdidas individuales más predecibles.', true, '2026-01-14 23:23:20.944788', '2026-01-14 23:23:20.944788') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4e23074b-7a08-4350-ac1c-b483bd8411e6', 'general_lines', NULL, 'What is hired and non-owned auto coverage?', '¿Qué es la cobertura de autos alquilados y no propios?', '["Coverage for owned vehicles", "Coverage for vehicles an employee uses for business that the business doesn''t own", "Personal auto coverage", "Motorcycle coverage"]', '["Cobertura para vehículos propios", "Cobertura para vehículos que un empleado usa para negocios que el negocio no posee", "Cobertura de auto personal", "Cobertura de motocicleta"]', 1, 'Hired and non-owned auto coverage provides liability protection when employees use rental cars or personal vehicles for business purposes.', 'La cobertura de autos alquilados y no propios proporciona protección de responsabilidad cuando los empleados usan autos de alquiler o vehículos personales para propósitos comerciales.', true, '2026-01-14 23:10:18.185356', '2026-01-14 23:10:18.185356') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4f3c6445-4f68-4d75-a215-2b2210794e95', 'general_lines', NULL, 'What is a loss exposure?', '¿Qué es una exposición a pérdidas?', '["An actual loss", "Any condition or situation that presents the possibility of loss", "An insurance policy", "A premium payment"]', '["Una pérdida real", "Cualquier condición o situación que presenta la posibilidad de pérdida", "Una póliza de seguro", "Un pago de prima"]', 1, 'A loss exposure is any condition, situation, or activity that could result in a financial loss, such as owning property or operating a business.', 'Una exposición a pérdidas es cualquier condición, situación o actividad que podría resultar en una pérdida financiera, como poseer propiedad u operar un negocio.', true, '2026-01-14 23:23:20.969198', '2026-01-14 23:23:20.969198') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('510c3960-4fb5-47c9-ac5d-1c5ec613a8c6', 'general_lines', NULL, 'What is risk retention?', '¿Qué es la retención de riesgos?', '["Transferring all risk", "The decision to absorb a risk and pay for losses out of one''s own resources", "Avoiding all risk", "Purchasing insurance"]', '["Transferir todo el riesgo", "La decisión de absorber un riesgo y pagar las pérdidas con recursos propios", "Evitar todo el riesgo", "Comprar seguro"]', 1, 'Risk retention is a risk management technique where the organization decides to absorb potential losses rather than transfer them to an insurer.', 'La retención de riesgos es una técnica de gestión de riesgos donde la organización decide absorber las pérdidas potenciales en lugar de transferirlas a un asegurador.', true, '2026-01-14 23:23:20.955242', '2026-01-14 23:23:20.955242') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5193afac-2b9d-4b9f-a7fa-91160aea1ddc', 'general_lines', NULL, 'What is rebating in insurance?', '¿Qué es el ''rebating'' en seguros?', '["A type of discount", "Giving part of the agent''s commission back to the insured as an inducement to purchase", "A premium refund", "A claims payment"]', '["Un tipo de descuento", "Dar parte de la comisión del agente al asegurado como incentivo para comprar", "Un reembolso de prima", "Un pago de reclamos"]', 1, 'Rebating is the illegal practice of giving any portion of an agent''s commission or something of value to the insured as an inducement to purchase insurance.', 'El rebating es la práctica ilegal de dar cualquier porción de la comisión de un agente o algo de valor al asegurado como incentivo para comprar seguro.', true, '2026-01-14 23:13:37.286588', '2026-01-14 23:13:37.286588') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('52234d0f-b38f-4a26-99a3-50da2ff85956', 'general_lines', NULL, 'What is general average in marine insurance?', '¿Qué es la avería gruesa en el seguro marítimo?', '["An average claim", "A maritime law principle where all parties share in losses from voluntary sacrifice to save the voyage", "A premium calculation", "A deductible"]', '["Un reclamo promedio", "Un principio de ley marítima donde todas las partes comparten pérdidas de sacrificio voluntario para salvar el viaje", "Un cálculo de prima", "Un deducible"]', 1, 'General average is a maritime law principle requiring all parties (ship, cargo owners) to share proportionally in losses from deliberate sacrifice to save the voyage.', 'La avería gruesa es un principio de ley marítima que requiere que todas las partes (barco, propietarios de carga) compartan proporcionalmente las pérdidas de sacrificio deliberado para salvar el viaje.', true, '2026-01-14 23:16:55.493036', '2026-01-14 23:16:55.493036') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('527f232f-de97-4fef-a301-39778ea6fdee', 'general_lines', NULL, 'What is employment practices liability insurance (EPLI)?', '¿Qué es el seguro de responsabilidad por prácticas de empleo (EPLI)?', '["Workers compensation", "Coverage for claims of discrimination, harassment, and wrongful termination", "Auto insurance", "Property insurance"]', '["Compensación de trabajadores", "Cobertura para reclamos de discriminación, acoso y terminación injusta", "Seguro de auto", "Seguro de propiedad"]', 1, 'EPLI covers claims by employees alleging discrimination, sexual harassment, wrongful termination, and other employment-related issues.', 'El EPLI cubre reclamos de empleados alegando discriminación, acoso sexual, terminación injusta y otros problemas relacionados con el empleo.', true, '2026-01-14 23:10:18.224677', '2026-01-14 23:10:18.224677') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('54bea775-a019-4a85-b467-c71ad45ddfd1', 'general_lines', NULL, 'What is computer fraud coverage?', '¿Qué es la cobertura de fraude informático?', '["Coverage for computer hardware", "Coverage for losses from unauthorized computer access or theft of funds", "Property coverage for computers", "Life insurance"]', '["Cobertura para hardware de computadora", "Cobertura por pérdidas de acceso no autorizado a computadoras o robo de fondos", "Cobertura de propiedad para computadoras", "Seguro de vida"]', 1, 'Computer fraud coverage protects against loss of money or securities resulting from fraudulent computer entry or unauthorized computer access.', 'La cobertura de fraude informático protege contra pérdida de dinero o valores resultante de entrada fraudulenta a computadoras o acceso no autorizado.', true, '2026-01-14 23:16:55.401967', '2026-01-14 23:16:55.401967') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('589b7e8a-e1da-4b72-af8b-bcb0a71d4120', 'general_lines', NULL, 'What is social engineering fraud coverage?', '¿Qué es la cobertura de fraude de ingeniería social?', '["Coverage for construction projects", "Coverage for losses from deceptive schemes that trick employees into transferring money", "Property coverage", "Auto coverage"]', '["Cobertura para proyectos de construcción", "Cobertura por pérdidas de esquemas engañosos que engañan a empleados para transferir dinero", "Cobertura de propiedad", "Cobertura de auto"]', 1, 'Social engineering fraud coverage protects against losses when employees are tricked into transferring money or securities through deceptive communications.', 'La cobertura de fraude de ingeniería social protege contra pérdidas cuando empleados son engañados para transferir dinero o valores a través de comunicaciones engañosas.', true, '2026-01-14 23:16:55.407341', '2026-01-14 23:16:55.407341') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('59563235-cf23-4868-ba69-1be111720ff9', 'general_lines', NULL, 'What is the purpose of the declarations page in an insurance policy?', '¿Cuál es el propósito de la página de declaraciones en una póliza de seguro?', '["To list exclusions", "To summarize key policy information such as named insured, coverage limits, and premium", "To define terms", "To list claims"]', '["Listar exclusiones", "Resumir información clave de la póliza como el asegurado nombrado, límites de cobertura y prima", "Definir términos", "Listar reclamos"]', 1, 'The declarations page (dec page) provides a summary of the policy including the named insured, policy period, coverage amounts, deductibles, and premium.', 'La página de declaraciones proporciona un resumen de la póliza incluyendo el asegurado nombrado, período de la póliza, montos de cobertura, deducibles y prima.', true, '2026-01-14 23:13:37.315489', '2026-01-14 23:13:37.315489') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('59b63c38-20a1-4338-985e-3834f4594ab3', 'general_lines', NULL, 'What does ''defense costs inside limits'' mean?', '¿Qué significa ''costos de defensa dentro de los límites''?', '["Defense costs are unlimited", "Defense costs reduce the available policy limits for claim payments", "Defense costs are not covered", "Defense costs are paid separately"]', '["Los costos de defensa son ilimitados", "Los costos de defensa reducen los límites de póliza disponibles para pagos de reclamos", "Los costos de defensa no están cubiertos", "Los costos de defensa se pagan por separado"]', 1, 'Defense costs inside limits means that attorneys'' fees and defense expenses reduce the policy limits available to pay claims.', 'Costos de defensa dentro de los límites significa que los honorarios de abogados y gastos de defensa reducen los límites de póliza disponibles para pagar reclamos.', true, '2026-01-14 23:16:55.545057', '2026-01-14 23:16:55.545057') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5a26fb5f-998f-400b-96e7-6aabd1177633', 'general_lines', NULL, 'What is insurable interest?', '¿Qué es el interés asegurable?', '["Interest earned on premiums", "A financial stake in the subject of insurance that would result in financial loss if damaged", "Interest in buying insurance", "A curiosity about insurance"]', '["Interés ganado sobre primas", "Una participación financiera en el objeto del seguro que resultaría en pérdida financiera si se daña", "Interés en comprar seguro", "Una curiosidad sobre seguros"]', 1, 'Insurable interest means the insured would suffer a financial loss if the insured property or person is damaged or dies.', 'El interés asegurable significa que el asegurado sufriría una pérdida financiera si la propiedad o persona asegurada se daña o muere.', true, '2026-01-14 23:13:37.330623', '2026-01-14 23:13:37.330623') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5aa1f750-5a5f-416d-a8cb-b6ff590e602a', 'general_lines', NULL, 'What is the principle of indemnity?', '¿Qué es el principio de indemnización?', '["The insured should be restored to their pre-loss condition, not profit from a loss", "Making a profit from insurance", "Getting more than the loss value", "A type of coverage"]', '["El asegurado debe ser restaurado a su condición previa a la pérdida, no beneficiarse de una pérdida", "Obtener ganancia del seguro", "Obtener más del valor de la pérdida", "Un tipo de cobertura"]', 0, 'The principle of indemnity states that insurance should restore the insured to their original financial position, not better.', 'El principio de indemnización establece que el seguro debe restaurar al asegurado a su posición financiera original, no mejor.', true, '2026-01-14 18:28:35.710211', '2026-01-14 18:28:35.710211') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5cc6ed00-561d-41b9-97fc-a91a637616d9', 'general_lines', NULL, 'What is a retroactive date in a claims-made policy?', '¿Qué es una fecha retroactiva en una póliza de reclamos hechos?', '["The policy expiration date", "The date before which claims for incidents are not covered", "The premium due date", "The renewal date"]', '["La fecha de vencimiento de la póliza", "La fecha antes de la cual los reclamos por incidentes no están cubiertos", "La fecha de vencimiento de la prima", "La fecha de renovación"]', 1, 'The retroactive date establishes the earliest date for which a claims-made policy will cover claims arising from incidents.', 'La fecha retroactiva establece la fecha más temprana para la cual una póliza de reclamos hechos cubrirá reclamos que surjan de incidentes.', true, '2026-01-14 23:10:18.227662', '2026-01-14 23:10:18.227662') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5cfcd9f9-6ccd-459b-82f9-799a51eb471b', 'general_lines', NULL, 'What does inland marine insurance typically cover?', '¿Qué cubre típicamente el seguro marítimo interior?', '["Ocean vessels only", "Property in transit and movable property", "Health care costs", "Life insurance"]', '["Solo embarcaciones oceánicas", "Propiedad en tránsito y propiedad móvil", "Costos de atención médica", "Seguro de vida"]', 1, 'Inland marine insurance covers property in transit, movable property, and property held by bailees, excluding ocean-going vessels.', 'El seguro marítimo interior cubre propiedad en tránsito, propiedad móvil y propiedad retenida por depositarios, excluyendo embarcaciones oceánicas.', true, '2026-01-14 23:10:18.121782', '2026-01-14 23:10:18.121782') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5f135aed-15ab-4d06-b857-a1d3f88f7c0f', 'general_lines', NULL, 'What is rate making in insurance?', '¿Qué es la tarificación en seguros?', '["Setting agent commissions", "The process of determining premium rates based on expected losses and expenses", "Paying claims", "Marketing insurance"]', '["Establecer comisiones de agentes", "El proceso de determinar tasas de primas basadas en pérdidas esperadas y gastos", "Pagar reclamos", "Comercializar seguros"]', 1, 'Rate making is the process insurers use to determine premium rates, considering expected losses, expenses, and profit margins.', 'La tarificación es el proceso que los aseguradores usan para determinar tasas de primas, considerando pérdidas esperadas, gastos y márgenes de ganancia.', true, '2026-01-14 23:23:20.902286', '2026-01-14 23:23:20.902286') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5f7c427d-883a-49e7-b8f6-fab56c61cca9', 'general_lines', NULL, 'What is a loss payee?', '¿Qué es un beneficiario de pérdida?', '["The insurance company", "A party with a financial interest who receives claim payments", "The insured", "The agent"]', '["La compañía de seguros", "Una parte con interés financiero que recibe pagos de reclamos", "El asegurado", "El agente"]', 1, 'A loss payee is a party, often a lender, with a financial interest in the insured property who is entitled to receive claim payments.', 'Un beneficiario de pérdida es una parte, a menudo un prestamista, con interés financiero en la propiedad asegurada que tiene derecho a recibir pagos de reclamos.', true, '2026-01-14 23:10:18.174762', '2026-01-14 23:10:18.174762') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('60ec0ca7-8676-4cd4-810b-ad7f920ce438', 'general_lines', NULL, 'What does ''aleatory'' mean regarding insurance contracts?', '¿Qué significa ''aleatorio'' respecto a los contratos de seguro?', '["Equal exchange of value", "The amounts exchanged by the parties may be unequal depending on whether a loss occurs", "Guaranteed payments", "No risk involved"]', '["Intercambio igual de valor", "Las cantidades intercambiadas por las partes pueden ser desiguales dependiendo de si ocurre una pérdida", "Pagos garantizados", "Sin riesgo involucrado"]', 1, 'Aleatory means the value exchanged by the parties is unequal—the insured pays premiums, but the insurer may pay nothing or a large claim depending on losses.', 'Aleatorio significa que el valor intercambiado por las partes es desigual—el asegurado paga primas, pero el asegurador puede no pagar nada o un gran reclamo dependiendo de las pérdidas.', true, '2026-01-14 23:13:37.348847', '2026-01-14 23:13:37.348847') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('61c7e537-f2aa-4af2-b793-227cda716631', 'general_lines', NULL, 'What is a bid bond?', '¿Qué es una fianza de licitación?', '["Insurance for property", "A guarantee that a contractor will honor their bid if selected", "A type of liability coverage", "An employee benefit"]', '["Seguro de propiedad", "Una garantía de que un contratista honrará su oferta si es seleccionado", "Un tipo de cobertura de responsabilidad", "Un beneficio para empleados"]', 1, 'A bid bond guarantees that a contractor will enter into a contract and provide required bonds if their bid is accepted.', 'Una fianza de licitación garantiza que un contratista celebrará un contrato y proporcionará las fianzas requeridas si su oferta es aceptada.', true, '2026-01-14 23:10:18.145154', '2026-01-14 23:10:18.145154') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6a7d5f68-afcf-4137-972b-1b4c0e528c26', 'general_lines', NULL, 'What is employee dishonesty coverage?', '¿Qué es la cobertura de deshonestidad de empleados?', '["Coverage for employee injuries", "Coverage for losses caused by dishonest acts of employees", "Health insurance", "Life insurance"]', '["Cobertura para lesiones de empleados", "Cobertura por pérdidas causadas por actos deshonestos de empleados", "Seguro de salud", "Seguro de vida"]', 1, 'Employee dishonesty coverage protects employers from losses caused by fraudulent or dishonest acts committed by employees.', 'La cobertura de deshonestidad de empleados protege a los empleadores de pérdidas causadas por actos fraudulentos o deshonestos cometidos por empleados.', true, '2026-01-14 23:16:55.388865', '2026-01-14 23:16:55.388865') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6b5dec50-cb6e-478a-a649-0d0b721f4da7', 'general_lines', NULL, 'In Texas, workers'' compensation is:', 'En Texas, la compensación de trabajadores es:', '["Mandatory for all employers", "Optional for most private employers", "Only for government employers", "Required only for large companies"]', '["Obligatoria para todos los empleadores", "Opcional para la mayoría de empleadores privados", "Solo para empleadores gubernamentales", "Requerida solo para grandes empresas"]', 1, 'Texas is unique in that workers'' compensation insurance is optional for most private employers, though they face certain liabilities if they don''t carry it.', 'Texas es único en que el seguro de compensación de trabajadores es opcional para la mayoría de empleadores privados, aunque enfrentan ciertas responsabilidades si no lo tienen.', true, '2026-01-14 23:10:18.192814', '2026-01-14 23:10:18.192814') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6c43b6ed-283e-480b-930f-4b700f309b8f', 'general_lines', NULL, 'What is a certificate of insurance?', '¿Qué es un certificado de seguro?', '["The actual policy document", "A document showing proof of insurance coverage", "A license to sell insurance", "A claim form"]', '["El documento de póliza real", "Un documento que muestra prueba de cobertura de seguro", "Una licencia para vender seguros", "Un formulario de reclamo"]', 1, 'A certificate of insurance is a document that provides evidence of insurance coverage, often required by third parties for contractual purposes.', 'Un certificado de seguro es un documento que proporciona evidencia de cobertura de seguro, a menudo requerido por terceros para propósitos contractuales.', true, '2026-01-14 23:10:18.129966', '2026-01-14 23:10:18.129966') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6ca64545-1c59-4875-b84c-4d048a5f7228', 'general_lines', NULL, 'What is the difference between occurrence and claims-made coverage?', '¿Cuál es la diferencia entre la cobertura por ocurrencia y la cobertura por reclamos hechos?', '["No difference", "Occurrence covers events during policy period; claims-made covers claims filed during policy period", "Claims-made is always more expensive", "Occurrence only covers property"]', '["Sin diferencia", "Ocurrencia cubre eventos durante el período de la póliza; reclamos hechos cubre reclamos presentados durante el período de la póliza", "Reclamos hechos siempre es más caro", "Ocurrencia solo cubre propiedad"]', 1, 'Occurrence coverage covers incidents that occur during the policy period regardless of when claims are filed, while claims-made covers claims filed during the policy period.', 'La cobertura por ocurrencia cubre incidentes que ocurren durante el período de la póliza sin importar cuándo se presenten los reclamos, mientras que reclamos hechos cubre reclamos presentados durante el período de la póliza.', true, '2026-01-14 23:10:18.103439', '2026-01-14 23:10:18.103439') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6cae3b63-2d8d-4f2f-bb71-f1b54146236c', 'general_lines', NULL, 'What is the purpose of a hold harmless agreement?', '¿Cuál es el propósito de un acuerdo de exoneración de responsabilidad?', '["To cancel insurance", "To transfer liability from one party to another", "To increase premiums", "To deny claims"]', '["Cancelar el seguro", "Transferir responsabilidad de una parte a otra", "Aumentar las primas", "Denegar reclamos"]', 1, 'A hold harmless agreement is a contractual provision where one party agrees to indemnify and hold the other party harmless from liability.', 'Un acuerdo de exoneración de responsabilidad es una disposición contractual donde una parte acuerda indemnizar y exonerar a la otra parte de responsabilidad.', true, '2026-01-14 23:10:18.142076', '2026-01-14 23:10:18.142076') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6e707e71-7f7b-40fc-8148-4248d836ffa7', 'general_lines', NULL, 'What is the difference between named perils and open perils coverage?', '¿Cuál es la diferencia entre cobertura de riesgos nombrados y riesgos abiertos?', '["No difference", "Named perils covers only listed risks; open perils covers all risks except those excluded", "Open perils is always cheaper", "Named perils covers more"]', '["Sin diferencia", "Riesgos nombrados cubre solo riesgos listados; riesgos abiertos cubre todos los riesgos excepto los excluidos", "Riesgos abiertos siempre es más barato", "Riesgos nombrados cubre más"]', 1, 'Named perils coverage only covers losses from specifically listed perils, while open perils (all-risk) covers all losses except those specifically excluded.', 'La cobertura de riesgos nombrados solo cubre pérdidas de riesgos específicamente listados, mientras que riesgos abiertos (todo riesgo) cubre todas las pérdidas excepto las específicamente excluidas.', true, '2026-01-14 23:10:18.126229', '2026-01-14 23:10:18.126229') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6e8bcd69-ae60-499c-befc-21283bb7f088', 'general_lines', NULL, 'What is the primary purpose of workers'' compensation insurance?', '¿Cuál es el propósito principal del seguro de compensación de trabajadores?', '["To provide life insurance to employees", "To provide benefits to employees injured or ill due to their job", "To cover property damage", "To provide auto coverage"]', '["Proporcionar seguro de vida a los empleados", "Proporcionar beneficios a empleados lesionados o enfermos debido a su trabajo", "Cubrir daños a la propiedad", "Proporcionar cobertura de auto"]', 1, 'Workers'' compensation insurance provides medical benefits and wage replacement to employees who suffer work-related injuries or illnesses.', 'El seguro de compensación de trabajadores proporciona beneficios médicos y reemplazo de salario a empleados que sufren lesiones o enfermedades relacionadas con el trabajo.', true, '2026-01-14 23:10:18.189326', '2026-01-14 23:10:18.189326') ON CONFLICT (id) DO NOTHING;
